<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { AlertCircle, CheckCircle2, ChevronRight, CircleHelp, ClipboardList, FileText, FolderOpen, LayoutDashboard, NotebookPen, Plus, Search, Settings2, X } from 'lucide-vue-next'
import Modal from './components/Modal.vue'
import Pager from './components/Pager.vue'
import RecordModal from './components/RecordModal.vue'
import TodayPage from './pages/TodayPage.vue'
import ProjectsPage from './pages/ProjectsPage.vue'
import TasksPage from './pages/TasksPage.vue'
import RecordsPage from './pages/RecordsPage.vue'
import WorklogsPage from './pages/WorklogsPage.vue'
import IssuesPage from './pages/IssuesPage.vue'
import SettingsPage from './pages/SettingsPage.vue'
import { api, loadProjects, messageOf, notify, projectName, query, ui } from './api'
import type { Attachment, Page, SearchHit } from './types'
const nav=[{id:'today',name:'今日',icon:LayoutDashboard},{id:'projects',name:'项目',icon:FolderOpen},{id:'tasks',name:'任务与 WBS',icon:ClipboardList},{id:'records',name:'现场记录',icon:NotebookPen},{id:'worklogs',name:'工作日志',icon:FileText},{id:'issues',name:'问题台账',icon:CircleHelp},{id:'settings',name:'设置与备份',icon:Settings2}]
function hashPage(){const page=location.hash.replace('#/','').split('?')[0];return nav.some(n=>n.id===page)?page:'today'}
const page=ref(hashPage()),revision=ref(0),recordOpen=ref(false),recordProject=ref(''),image=ref<Attachment>(),searchOpen=ref(false),searchText=ref(''),searching=ref(false),searchError=ref(''),hits=ref<SearchHit[]>([]),searchTotal=ref(0),searchOffset=ref(0),taskProject=ref(''),taskQuery=ref(''),recordQuery=ref(''),issueQuery=ref('');const searchLimit=30
const worklogPage=ref<{canLeave:()=>boolean}>()
const pageName=computed(()=>nav.find(n=>n.id===page.value)?.name||'今日');let searchTimer:ReturnType<typeof setTimeout>|undefined;let searchRequest=0
function navigate(id:string){if(page.value==='worklogs'&&id!=='worklogs'&&worklogPage.value&&!worklogPage.value.canLeave())return;page.value=id;location.hash=`/${id}`;document.querySelector('main')?.scrollTo(0,0)}
function onHash(){const next=hashPage();if(page.value==='worklogs'&&next!=='worklogs'&&worklogPage.value&&!worklogPage.value.canLeave()){location.hash='/worklogs';return}page.value=next}
function quickNote(project=''){recordProject.value=project;recordOpen.value=true}
function changed(){revision.value++;void loadProjects().catch(error=>notify(messageOf(error),true))}
function openTasks(id:string){taskProject.value=id;taskQuery.value='';navigate('tasks')}
async function doSearch(offset=0){searchOffset.value=offset;const q=searchText.value.trim();const request=++searchRequest;if(!q){hits.value=[];searchTotal.value=0;searching.value=false;return}searching.value=true;searchError.value='';try{const data=await api<Page<SearchHit>>(`/api/search?${query({q,limit:searchLimit,offset})}`);if(request===searchRequest){hits.value=data.items;searchTotal.value=data.total}}catch(e){if(request===searchRequest)searchError.value=messageOf(e)}finally{if(request===searchRequest)searching.value=false}}
function searchInput(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>void doSearch(),250)}
function openHit(hit:SearchHit){const type=hit.entity_type.replace(/s$/,'');if(type==='project'){navigate('projects')}else if(type==='task'){taskProject.value=hit.project_id;taskQuery.value=hit.title;navigate('tasks')}else if(type==='record'){recordQuery.value=hit.title||searchText.value;navigate('records')}else if(type==='issue'){issueQuery.value=hit.title;navigate('issues')}else if(type==='worklog'){navigate('worklogs')}searchOpen.value=false}
function typeName(type:string){return ({project:'项目',task:'任务',record:'记录',issue:'问题',worklog:'日志'} as Record<string,string>)[type.replace(/s$/,'')]||type}
function keydown(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchOpen.value=true}else if(event.altKey&&event.key.toLowerCase()==='n'){event.preventDefault();quickNote()}}
onMounted(()=>{window.addEventListener('hashchange',onHash);window.addEventListener('keydown',keydown);void loadProjects().catch(error=>notify(messageOf(error),true))});onUnmounted(()=>{window.removeEventListener('hashchange',onHash);window.removeEventListener('keydown',keydown);clearTimeout(searchTimer)})
</script>
<template><div class="app-shell"><aside class="sidebar"><a class="brand" href="#/today" aria-label="ProjNote 今日工作台"><span class="brand-mark"><i/><i/></span><div><strong>ProjNote</strong><span>项目管理工作台</span></div></a><div class="nav-group-label">工作空间</div><nav aria-label="主导航"><a v-for="item in nav" :key="item.id" :href="`#/${item.id}`" :class="{active:page===item.id,'mobile-settings':item.id==='settings'}" :aria-current="page===item.id?'page':undefined"><component :is="item.icon" :size="19"/><span>{{item.name}}</span><ChevronRight v-if="page===item.id" :size="15" class="nav-current"/></a></nav><div class="sidebar-bottom"><a class="settings-nav" href="#/settings" :class="{active:page==='settings'}"><Settings2 :size="18"/>设置与备份</a><div class="local-space"><span class="local-dot"/><div><strong>本地工作空间</strong><span>资料保存在这台电脑</span></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">我的工作空间<ChevronRight :size="14"/><strong>{{pageName}}</strong></div><div class="top-actions"><button class="search-launcher" @click="searchOpen=true"><Search :size="16"/><span>搜索项目、任务、记录</span><kbd>Ctrl K</kbd></button><button class="button primary quick-button" @click="quickNote()"><Plus :size="17"/>速记<kbd>Alt N</kbd></button></div></header><main id="main-content" tabindex="-1"><TodayPage v-if="page==='today'" :revision="revision" @record="quickNote()" @navigate="navigate" @image="image=$event"/><ProjectsPage v-else-if="page==='projects'" :revision="revision" @changed="changed" @tasks="openTasks"/><TasksPage v-else-if="page==='tasks'" :revision="revision" :initial-project="taskProject" :initial-query="taskQuery" @changed="changed"/><RecordsPage v-else-if="page==='records'" :revision="revision" :initial-query="recordQuery" @record="quickNote" @image="image=$event"/><WorklogsPage ref="worklogPage" v-else-if="page==='worklogs'" :revision="revision" @changed="changed"/><IssuesPage v-else-if="page==='issues'" :revision="revision" :initial-query="issueQuery" @changed="changed"/><SettingsPage v-else @changed="changed"/></main></div><Transition name="toast"><div v-if="ui.toast" class="toast" :class="{error:ui.error}" :role="ui.error?'alert':'status'"><AlertCircle v-if="ui.error" :size="19"/><CheckCircle2 v-else :size="19"/><span>{{ui.toast}}</span><button aria-label="关闭提示" @click="ui.toast=''"><X :size="16"/></button></div></Transition><RecordModal :open="recordOpen" :project-id="recordProject" @close="recordOpen=false" @saved="changed"/><Modal :open="!!image" :title="image?.filename||'查看图片'" wide @close="image=undefined"><div class="image-viewer" v-if="image"><img :src="image.url||`/api/attachments/${image.id}`" :alt="image.filename"/><a class="button subtle small" :href="`/api/attachments/${image.id}`" :download="image.filename">下载原图</a></div></Modal><Modal :open="searchOpen" title="搜索工作空间" wide @close="searchOpen=false"><div class="modal-body search-body"><form class="search-form" @submit.prevent="doSearch()"><Search :size="20"/><input v-model="searchText" autofocus placeholder="项目、任务、现场记录、问题…" aria-label="全局搜索关键词" @input="searchInput"/><button class="button primary small" type="submit">搜索</button></form><p v-if="searchError" class="form-error" role="alert">{{searchError}}</p><p v-else-if="searching" class="loading-message">正在搜索…</p><div v-else-if="!searchText.trim()" class="search-empty">输入关键词，查找工作空间中的内容。</div><div v-else-if="!hits.length" class="search-empty">没有找到相关内容，请换一个关键词。</div><div v-else class="search-results"><button v-for="(hit,index) in hits" :key="`${hit.entity_type}-${hit.entity_id}-${index}`" @click="openHit(hit)"><span class="badge">{{typeName(hit.entity_type)}}</span><div><strong>{{hit.title||'无标题记录'}}</strong><p>{{hit.body}}</p><small>{{hit.project_id?projectName(hit.project_id):'工作空间'}}</small></div><ChevronRight :size="17"/></button></div><p v-if="searchTotal>=500" class="input-hint">首版最多返回 500 条结果，请增加关键词缩小范围。</p><Pager :offset="searchOffset" :limit="searchLimit" :total="searchTotal" @change="doSearch"/></div></Modal></div></template>
